        "type": "prometheus",
        "uid": "aj-prometheus"
      },
      "gridPos": {
        "x": 0,
        "y": 0,
        "w": 12,
        "h": 8
      },
      "targets": [
        {
          "expr": "aj_outbox_pending",
          "refId": "A",
          "legendFormat": "{{service}}{{queue}}{{pod}}{{deployment}}"
        }
      ],
      "fieldConfig": {
        "defaults": {
          "min": 0
        },
        "overrides": []
      },
      "options": {}
    },
    {
      "id": 2,
      "title": "\u00c6ldste ventende afsendelse (sekunder)",
      "description": "Age of oldest outbox event.",
      "type": "timeseries",
      "datasource": {
        "type": "prometheus",
        "uid": "aj-prometheus"
      },
      "gridPos": {
        "x": 12,
        "y": 0,
        "w": 12,
        "h": 8
      },
